async function main() {
  const pages = figma.root.children;
  const pageList = pages.map(p => ({ id: p.id, name: p.name }));
  console.log("Pages:", JSON.stringify(pageList));

  // Find components page and media page
  const compPage = pages.find(p => p.name.includes("Components"));
  const mediaPage = pages.find(p => p.name.includes("Media"));
  const startPage = pages.find(p => p.name.includes("Start Here"));

  const components = [];
  if (compPage) {
    const nodes = compPage.findAll(n => n.type === "COMPONENT" || n.type === "COMPONENT_SET");
    nodes.forEach(n => components.push({ id: n.id, name: n.name, type: n.type }));
  }

  const media = [];
  if (mediaPage) {
    const nodes = mediaPage.findAll(n => n.type === "COMPONENT" || n.type === "COMPONENT_SET");
    nodes.forEach(n => media.push({ id: n.id, name: n.name, type: n.type }));
  }

  return {
    pages: pageList,
    componentsCount: components.length,
    components,
    mediaCount: media.length,
    media
  };
}

