(async () => {
  const button = figma.getNodeById("1:23");
  const field = figma.getNodeById("1:26");

  function getFullProperties(n) {
    const props = {
      id: n.id,
      name: n.name,
      type: n.type,
      width: n.width,
      height: n.height,
      fills: n.fills,
      strokes: n.strokes,
      strokeWeight: n.strokeWeight,
      cornerRadius: n.cornerRadius,
      paddingLeft: n.paddingLeft,
      paddingRight: n.paddingRight,
      paddingTop: n.paddingTop,
      paddingBottom: n.paddingBottom,
      itemSpacing: n.itemSpacing,
      layoutMode: n.layoutMode,
      primaryAxisSizingMode: n.primaryAxisSizingMode,
      counterAxisSizingMode: n.counterAxisSizingMode,
      primaryAxisAlignItems: n.primaryAxisAlignItems,
      counterAxisAlignItems: n.counterAxisAlignItems
    };
    if (n.children) {
      props.children = n.children.map(getFullProperties);
    }
    if (n.type === "TEXT") {
      props.characters = n.characters;
      props.fontName = n.fontName;
      props.fontSize = n.fontSize;
      props.letterSpacing = n.letterSpacing;
      props.lineHeight = n.lineHeight;
      props.textAlignHorizontal = n.textAlignHorizontal;
      props.textAlignVertical = n.textAlignVertical;
    }
    return props;
  }

  return {
    button: getFullProperties(button),
    field: getFullProperties(field)
  };
})()

